    <div class="stats">${N("\u062C\u0645\u0639 \u0628\u062F\u0647\u06A9\u0627\u0631",g(a.debit),"\u06A9\u0644 \u06AF\u0631\u062F\u0634","pos")}${N("\u062C\u0645\u0639 \u0628\u0633\u062A\u0627\u0646\u06A9\u0627\u0631",g(a.credit),"\u06A9\u0644 \u06AF\u0631\u062F\u0634","neg")}</div>
